INSERT INTO `screening_execution` (`id`, `created_at`, `execution_message`, `raw_response`, `status`, `client_id`, `ubo_id`) VALUES (136, '2026-06-16 15:08:07.560689', 'Client checked at:2026-06-16T15:08:07.808686258 Status: PASSED', '{"limit": 5, "responses": {"query-1": {"query": {"id": null, "schema": "Person", "properties": {"name": ["Roman Abramovich"], "country": ["ru"]}}, "total": {"value": 2, "relation": "eq"}, "status": 200, "results": [{"id": "Q171428", "match": true, "score": 1.0, "schema": "Person", "target": true, "caption": "Roman Abramovich", "datasets": ["base_de_donnees_principale"], "last_seen": "2026-04-05T18:44:50", "referents": ["mc-freezes-206ec74f5da7801e2f601e7526a86a52eb0a6b47", "gb-fcdo-rus0270", "eu-tb-logical-137652", "nz-ru-ind-460-roman-abramovich", "acf-62f26ac19393a99e79eb2a1f2a4ac9b583a0c2ab", "fr-ga-4484", "gb-hmt-14212", "eu-fsf-eu-7792-75", "be-fod-f2c5556e11215a4b55ed193e0c8e43ce877ea7a0", "ca-sema-db1ed240a7cf6d2f8ced3aed865597284a2f2e95", "ch-seco-52253", "ua-nsdc-19863-abramovic-roman-arkadijovic", "au-dfat-6754-roman-arkadyevich-abramovich", "gb-coh-psc-11630296--fz-abkr31emymttazx4uej2m5c", "gb-coh-5iglfnbosofovx-t0szltysakw"], "first_seen": "2021-02-08T00:00:00", "properties": {"name": ["Abramovich Roman", "Roman Abramovich", "?????? ??????????????", "???? ??????????", "????????????", "Roman Abramóvitx", "Abramovich Roman Arkadyevich", "????? ?????????", "????? ??????????", "Roman Arkadyevich ABRAMOVICH", "????? ??????????", "Roman Abramovitj", "Román Abramóvich", "Roman Abrahamoviç", "Roman Abramovitch", "Roman Abramovitš", "Roman ABRAMOVICH", "Roman Abramovítsj", "Roman Abramoviç", "Romanas Abramovi?ius", "???? ?????????", "Roman Abramowicz", "Roman Abramovi?", "????? ??????????", "Roman Abramovitsj", "Rom?ns Abramovi?s", "Roman Abramovici", "????? ?????????", "???? ????????\'", "????? ?????????? ?????????", "Roman Abramovics", "????????? ????? ???????????", "Roman Arkadjevitj ABRAMOVITJ", "Roman Arkadjewitsch Abramowitsch", "??·???????·??????", "????????? ????? ??????????", "?? ??????", "????? ?????????? ?????????", "Mr Roman Abramovich", "????? ???????????", "Roman Arkadyevich Abramovich"], "alias": ["???? ?????????", "Romans Abramovi?s", "Roman Arkad?vi? Abramovi?", "Roman Abbramovich", "???? ?????????", "Roman Abramovi?", "Abramovich Roman Arkadyevich", "Roman Abrammovic", "?????? ??????????? ??????????", "Roman Arkadevitj Abramovitj", "Roman Abramovits", "Roman Arkadiévich Abramóvich", "Roman Arkadievich Abramóvich", "Roman Arkadievich Abramovich", "????? ?????????? ?????????", "Roman Abrámovich", "????????? ?. ?.", "Roman Arkadiévich Abramovich", "Román Abramovich", "????????? ?????", "Abramovych Roman Arkadiiovych", "Roman Abramovi?", "????????? ????? ??????????", "Roman Abramóvich", "Roman Abramovici", "????? ?????????", "?? ?????", "Roman Abramovic", "Roman Arkàdievitx Abramóvitx", "Roman Arkadjevitj Abramovitj", "????? ?????????? ?????????", "Roman Arcadyevich Abramovich", "????? ?????????? ?????????", "?????????, ?????", "???? ????????? ?????????", "Roman Abràmovitx", "Roman Arkadjevitš Abramovitš", "Roman Arkadyevich Abrahamovic", "????? ??????????? ?????????", "?????? ??????????? ??????????", "Roman Abrammovich", "Roman Abramòvitx", "Roman Abramovitsh", "Roman Arkadievici Abramovici", "Román Abrámovich", "Roman Abromoviç", "???? ????????\' ????????\'", "????????? ????? ??????????", "Roman Arkadievi? Abramovi?", "Roman Arkadyevich Abramovich", "Roman Arkad\'evi? Abramovi?", "Roman Arkadiewicz Abramowicz", "Roman Abramowitsch"], "notes": ["Personnes associées: le président de la Fédération de Russie Vladimir Poutine Roman Abramovich est un homme d’affaires influent russe qui entretient des liens étroits et de longue date avec le président de la Fédération de Russie Vladimir Poutine. Il a bénéficié d’un accès privilégié au président et conserve de très bonnes relations avec lui. Ce lien avec le dirigeant russe l’a aidé à préserver sa fortune qui est considérable. Il est l’un des principaux actionnaires du groupe sidérurgique Evraz, qui est l’un des plus grands contribuables de la Russie. Roman Abramovich est également actionnaire de la société russe Norilsk Nickel, l’un des plus grands producteurs de palladium au monde et grande entreprise de nickel raffiné dans le secteur minier, qui fournit des revenus substantiels au gouvernement russe. Il est donc un homme d’affaires russe influent exerçant des activités en Russie ainsi qu’un homme d’affaires intervenant dans des secteurs économiques fournissant une source substantielle de revenus au gouvernement de la Fédération de Russie, qui est responsable de l’annexion de la Crimée et de la déstabilisation de l’Ukraine.", "Mentioned in 2018 CAATSA report on Russian oligarchs", "Russian-Israeli oligarch and politician", "Owner of Millhouse Capital", "Associated individuals: the President of the Russian Federation Vladimir Putin", "???????????, ??????????, ?????????? ?? ???? ???????????? ?????? (???????), ??????????? ???????? 146, ?????????????? ????? ?????????? ????????? ?????? ?????????? ?? ?????? ???????? ????????? ???????? ??????? ?? ????? ???????", "Associated individuals: Vladimir Putin, President of the Russian Federation.", "Transport sanctions: ships owned, controlled, chartered or operated by the individual are prohibited from entering a port in the UK; may be given a movement or a port entry direction, can be detained, and will be refused permission to register on the UK Ship Register or have its existing registration terminated. An aircraft owned, chartered or operated by the individual is prohibited from overflying or landing in the UK, may be given a movement direction, can be detained or moved to a specified airport, and will be refused permission to register on the CAA Aircraft Register or have its existing registration terminated. The Director Disqualification Sanction was imposed on 09/04/2025.", "Personne associée : le président de la Fédération de Russie Vladimir Poutine", "Russian-Israeli oligarch, and politician", "Roman Abramovich is a Russian oligarch who has long and close ties to Vladimir Putin. He has had privileged access to the president, and has maintained very good relations with him. This connection with the Russian leader helped him maintain his considerable wealth. He is a major shareholder of the steel group Evraz, which is one of Russia’s largest taxpayers. He has therefore been benefitting from Russian decision-makers responsible for the annexation of Crimea and the destabilisation of Ukraine. He is also one of the leading Russian businesspersons involved in economic sectors providing a substantial source of revenue to the Government of the Russian Federation, which is responsible for the annexation of Crimea and the destabilisation of Ukraine.\\nInvolved in corruption schemes of PJSC Gazprom and its subsidiaries. Participated in the formation of corrupt sources of income for Vladimir Putin and his closest associates.", "Function: Leading businessperson close to the President of the Russian Federation Vladimir Putin; major shareholder of Evraz; former Governor of Chukotka", "He is a Russian oligarch with longstanding and close ties to Vladimir Putin dating back to the late 1990s. He was part of the circle that Putin owed his presidency to as the successor to Russia\'s first president, Boris Yeltsin. Abramovich has enjoyed privileged access to the president and has maintained a strong relationship with him, a connection that has helped him preserve his considerable wealth. He ranked 16th on Forbes\' list of \\"\\"125 Billionaires of Russia,\\"\\" with a fortune of 9.7 billion USD. He is a major shareholder of the steel group Evraz, directly owning 28.64% of the shares. Evraz is one of Russia’s largest taxpayers and supplies raw materials to Uralvagonzavod, a producer of tanks and civilian products, as well as other companies in the defense industry.\\n\\nIn addition to Evraz, Abramovich also owns shares in other major Russian companies such as Norilsk Nickel, Yandex, and Renaissance Insurance. His business ventures have benefitted from Russian decision-makers responsible for the annexation of Crimea and the destabilization of Ukraine. He is one of the leading Russian business figures involved in economic sectors that provide substantial revenue to the Russian government, which is responsible for these actions. Despite the ongoing war, Abramovich remains entangled in Russia’s system of political corruption, where capital serves as a tool for acquiring political influence, and political influence is essential for preserving capital at the highest levels.\\n\\nRoman Abramovich is also involved in corruption schemes related to Gazprom PJSC and its subsidiaries, playing a role in generating corrupt income for Vladimir Putin and his closest associates.", "Disqualified", "Roman Abramovich is a Russian leading businessperson who has long and close ties to the President of the Russian Federation Vladimir Putin. He has had privileged access to the President, and has maintained very good relations with him. This connection with the Russian leader has helped him to maintain his considerable wealth. He is a major shareholder of the steel group Evraz, which is one of Russia’s largest taxpayers. Roman Abramovich is also a shareholder of the Russian company Norilsk Nickel, one of the world\'s largest palladium producers and a major refined nickel company in the mining sector, which provides substantial revenues to the Russian government. He is therefore a leading Russian businessperson operating in Russia and a businessperson involved in economic sectors providing a substantial source of revenue to the Government of the Russian Federation, which is responsible for the annexation of Crimea and the destabilisation of Ukraine.", "(Date of UN designation: 2022-03-15)"], "title": ["Mr"], "gender": ["male"], "topics": ["corp.disqual", "sanction", "role.oligarch", "role.pol", "poi", "role.pep"], "address": ["Apartment 35.1 1 Waterfront Drive, London SW10 0AA, England", "1 Lipovaya Aleya, Nemchinovo, district d\'Odinstvo, Moscou, Russie", "1 Lipovaya Aleya, Nemchinovo, Russian Federation", "1, Lipovaya Aleya, Nemchinovo, Odinsovo district, Moscow, RUSSIAN FEDERATION", "1 Lipovaya Aleya, Nemchinovo, district d’Odinsovo, Moscou, Russie"], "country": ["ru"], "innCode": ["770770715160"], "lastName": ["?????????", "ABRAMOVITJ", "ABRAMOVICH", "Abramovi?", "Abramovich", "Abramovici"], "position": ["Businessperson. Former governor of Chukotka. Major shareholder of Evraz also a shareholder of the Russian company Norilsk Nickel,\\none oí the world’s largest palladium producers and a major refined nickel company in the mining sector", "homme d’affaires influent proche du président de la Fédération de Russie, Vladimir Poutine ; actionnaire majeur d’Evraz ; ancien gouverneur de Tchoukotka", "member of the State Duma (2000-2000)", "homme d\'affaires influent proche de Vladimir Poutine;", "Governor of Chukotka Autonomous Okrug (2000-2008)", "Actionnaire principal d\'Evraz", "Businessperson. Former governor of Chukotka. Major shareholder of Evraz also a shareholder of the Russian company Norilsk Nickel, one oí the world’s largest palladium producers and a major refined nickel company in the mining sector", "Stakeholder in Evraz PLC and Norilsk Nickel", "Ancien gouverneur de Tchoukotka"], "religion": ["Judaism"], "birthDate": ["1966-10-24"], "createdAt": ["2022-03-14"], "education": ["Gubkin University", "Moscow State Law University"], "firstName": ["Roman Arkadyevich", "?????", "Roman"], "programId": ["NZ-RSA2022", "GB-RUS", "AU-RUSSIA", "CA-SEMA", "SECO-UKRAINE", "UA-SA1644", "EU-UKR"], "sourceUrl": ["https://find-and-update.company-information.service.gov.uk/disqualified-officers/natural/5igLfNboSOFovx--t0SZLTYsAKw", "https://gels-avoirs.dgtresor.gouv.fr/Gels/RegistreDetail?idRegistre=4484", "https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=OJ%3AL_202500527&qid=1742218670627